const raw = items[0] ?? {};
const data = raw.json?.response ?? raw.json ?? {};
const error = raw.error ?? raw.json?.error ?? data?.error;

function errorDetail() {
  if (typeof error === 'string' && error) return error;
  if (error?.message) return error.message;
  if (raw.json?.message) return raw.json.message;
  if (data?.message) return data.message;
  return 'unexpected response';
}

if (data?.should_send === false && data?.skip_reason === 'market_closed') {
  return [];
}

if (error || !data?.indices?.sp500 || !data?.indices?.nasdaq) {
  return [{
    json: {
      message: `market_api 브리핑 호출 실패\n${errorDetail()}`,
      briefing_ok: false,
      should_send: false,
    },
  }];
}

function formatNumber(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(num);
}

function formatSigned(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  const sign = num > 0 ? '+' : '';
  return `${sign}${num.toFixed(2)}`;
}

function formatPct(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  const sign = num > 0 ? '+' : '';
  return `${sign}${num.toFixed(2)}%`;
}

function formatKstNow() {
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });
  const parts = Object.fromEntries(
    formatter.formatToParts(new Date()).map((part) => [part.type, part.value]),
  );
  return `${parts.year}. ${parts.month}. ${parts.day}. ${parts.hour}:${parts.minute} KST`;
}

const sp = data.indices.sp500;
const nasdaq = data.indices.nasdaq;
const sentAtKst = formatKstNow();

return [{
  json: {
    briefing_ok: true,
    should_send: true,
    message: [
      '미국 증시 마감 브리핑',
      `기준일: ${data.market_date ?? data.target_session_date ?? '-'}`,
      `발송시각: ${sentAtKst}`,
      `S&P 500: ${formatNumber(sp.close)} (${formatSigned(sp.change)}, ${formatPct(sp.change_pct)})`,
      `Nasdaq: ${formatNumber(nasdaq.close)} (${formatSigned(nasdaq.change)}, ${formatPct(nasdaq.change_pct)})`,
    ].join('\n'),
  },
}];

