const raw = items[0] ?? {};
const data = raw.json?.response ?? raw.json ?? {};
const error = raw.error ?? raw.json?.error ?? data?.error;

function errorDetail() {
  if (typeof error === 'string' && error) return error;
  if (error?.message) return error.message;
  if (raw.json?.message) return raw.json.message;
  if (data?.message) return data.message;
  return 'unexpected response';
}

if (data?.should_send === false && data?.skip_reason === 'market_closed') {
  return [];
}

if (error || typeof data?.rsi === 'undefined' || typeof data?.close === 'undefined') {
  return [{
    json: {
      message: `market_api RSI 체크 실패\n${errorDetail()}`,
    },
  }];
}

function formatNumber(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(num);
}

function formatSignedMoney(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  const sign = num > 0 ? '+' : num < 0 ? '-' : '';
  return `${sign}$${formatNumber(Math.abs(num))}`;
}

function formatSignedPct(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  const sign = num > 0 ? '+' : num < 0 ? '-' : '';
  return `${sign}${Math.abs(num).toFixed(2)}%`;
}

function formatSignedValue(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 'N/A';
  const sign = num > 0 ? '+' : num < 0 ? '-' : '';
  return `${sign}${Math.abs(num).toFixed(2)}`;
}

function escapeTelegramText(value) {
  return String(value ?? '-').replace(/_/g, '\\_');
}

const symbol = data.symbol ?? 'QLD';
const rsiValue = Number(data.rsi);
const rsiText = Number.isFinite(rsiValue) ? rsiValue.toFixed(2) : 'N/A';
const lines = [
  `${symbol} 가격 & RSI 체크`,
  `기준일: ${data.market_date ?? data.target_session_date ?? '-'}`,
  `종가: $${formatNumber(data.close)} (${formatSignedMoney(data.change)}, ${formatSignedPct(data.change_pct)})`,
  `RSI(14): ${rsiText} (${formatSignedValue(data.rsi_change)})`,
  `상태: ${escapeTelegramText(data.state ?? '-')}`,
];

if (data.changed && data.previous_state) {
  const eventText = data.event === 'ENTER_UNDER_30'
    ? '재진입 준비 신호'
    : data.event === 'EXIT_UNDER_30'
      ? '과매도 해제'
      : '상태 변경';
  lines.push(`상태변경: ${escapeTelegramText(data.previous_state)} -> ${escapeTelegramText(data.state ?? '-')}`);
  lines.push(`이벤트: ${eventText}`);
}

return [{
  json: {
    message: lines.join('\n'),
  },
}];
